import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.BWTY_seE.js";const g=JSON.parse('{"title":"AI 动态 · 2026-11-24","description":"","frontmatter":{"title":"AI 动态 · 2026-11-24","date":"2026-11-24T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-24.md","filePath":"news/2026-11/ai-news-2026-11-24.md","lastUpdated":null}'),s={name:"news/2026-11/ai-news-2026-11-24.md"};function i(o,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-11-24" tabindex="-1">AI 动态 · 2026-11-24 <a class="header-anchor" href="#ai-动态-·-2026-11-24" aria-label="Permalink to &quot;AI 动态 · 2026-11-24&quot;">​</a></h1><blockquote><p>截至 2026-11-24。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>英伟达董事会撤销解职决定、黄仁勋回归，成为今日最大公司治理与市场事件，相关报道贯穿多家媒体。</li><li>Anthropic 推出 Claude Ship，让 Agent 直接评审、修复并批准 GitHub PR；OpenAI 与 Cisco 开源 Shirudo Linux 运行时，Agent 开始进入代码与系统安全核心流程。</li><li>模型侧 Z.ai 发布 750B 循环 Transformer GLM-5.4，OpenAI 展示 GPT-6 的蛋白质设计能力，Agent 基础设施与安全议题同步升温。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="头条-·-亚马逊收购-decart-以软件缩小与英伟达的芯片差距" tabindex="-1">头条 · 亚马逊收购 Decart，以软件缩小与英伟达的芯片差距 <a class="header-anchor" href="#头条-·-亚马逊收购-decart-以软件缩小与英伟达的芯片差距" aria-label="Permalink to &quot;头条 · 亚马逊收购 Decart，以软件缩小与英伟达的芯片差距&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/7b6b9fa3bd23.webp" alt="配图"></p><p>亚马逊以据报道 75 亿美元收购 Decart，意在提升自研 Trainium 芯片的效率。报道将这笔交易解读为用软件能力弥补硬件代差，减少对英伟达 GPU 的依赖。对读者：若使用 AWS 训练推理，可跟进 Trainium 软件栈的后续更新与迁移成本。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/24/amazons-decart-acquisition-is-a-bet-on-using-software-to-narrow-the-gap-with-nvidia-in-the-ai-chip-race/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="supertake-融资-2000-万美元-用-ai-agent-把市场预测变成股票组合" tabindex="-1">Supertake 融资 2000 万美元，用 AI Agent 把市场预测变成股票组合 <a class="header-anchor" href="#supertake-融资-2000-万美元-用-ai-agent-把市场预测变成股票组合" aria-label="Permalink to &quot;Supertake 融资 2000 万美元，用 AI Agent 把市场预测变成股票组合&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/e726bca6dc72.webp" alt="配图"></p><p>Supertake 完成 2000 万美元融资，用户只需表达对市场走向的判断，AI Agent 负责将其转化为具体股票组合，无需自己选股。这代表 Agent 在个人理财场景的进一步落地。对读者：此类产品涉及投资建议合规与模型风险，跟进时重点看其披露与风控机制。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/23/supertake-raises-20m-to-let-ai-agents-turn-your-market-predictions-into-stock-portfolios/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="多州起诉-spacex-要求阻止-grok-生成儿童性图像与报复性色情内容" tabindex="-1">多州起诉 SpaceX，要求阻止 Grok 生成儿童性图像与报复性色情内容 <a class="header-anchor" href="#多州起诉-spacex-要求阻止-grok-生成儿童性图像与报复性色情内容" aria-label="Permalink to &quot;多州起诉 SpaceX，要求阻止 Grok 生成儿童性图像与报复性色情内容&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/d11c54a45ebe.jpg" alt="配图"></p><p>多个州总检察长起诉 SpaceX，要求停止 Grok 生成儿童性虐待材料和报复性色情图像。X 方面称每条 Grok 输出都经过筛查，但州检方认为问题仍在持续。对读者：生成式产品的输出审核与年龄验证正成为监管焦点，相关团队应提前审视内容安全策略。</p><p class="news-entry-source"><a href="https://arstechnica.com/tech-policy/2026/11/states-sue-spacex-to-stop-grok-from-generating-child-sex-images-revenge-porn/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="mcp-服务器可在-claude-中分发技能、执行任务" tabindex="-1">MCP 服务器可在 Claude 中分发技能、执行任务 <a class="header-anchor" href="#mcp-服务器可在-claude-中分发技能、执行任务" aria-label="Permalink to &quot;MCP 服务器可在 Claude 中分发技能、执行任务&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/76c6da9cb10e.webp" alt="配图"></p><p>Claude 的 Skills over MCP 进入公测，MCP 服务器可在提供工具的同时分发技能；Tasks 与 Elicitation 正式可用，File Uploads 即将推出。这让 MCP 从工具连接协议扩展为能力分发层。对读者：维护 MCP 服务器的团队可评估把常用工作流封装为技能，降低客户端集成成本。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/skills-over-mcp-tasks-and-more" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-工件可变成-mac-和-windows-应用" tabindex="-1">Claude 工件可变成 Mac 和 Windows 应用 <a class="header-anchor" href="#claude-工件可变成-mac-和-windows-应用" aria-label="Permalink to &quot;Claude 工件可变成 Mac 和 Windows 应用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/478f8a0eb604.webp" alt="配图"></p><p>Claude 在 Mac 与 Windows 桌面端推出 beta 功能，用户可把常用工件像普通应用一样打开，并让它们在电脑上执行更多操作。这模糊了对话产物与本地应用的边界。对读者：若用工件做内部小工具，可关注其权限边界与数据留存策略。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/install-as-app" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="google-搜索接入-personal-intelligence-结果更个性化" tabindex="-1">Google 搜索接入 Personal Intelligence，结果更个性化 <a class="header-anchor" href="#google-搜索接入-personal-intelligence-结果更个性化" aria-label="Permalink to &quot;Google 搜索接入 Personal Intelligence，结果更个性化&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google AI Blog</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/f1496aa6d35d.png" alt="配图"></p><p>Google 允许用户主动选择将 Wallet、Drive 与 Gemini 应用连接到 AI Mode 的 Personal Intelligence，从而获得更贴合个人情境的搜索回答。个性化与隐私的取舍被摆上台面。对读者：企业若依赖 Google 生态做客户触达，需关注用户授权范围变化对数据可见性的影响。</p><p class="news-entry-source"><a href="https://blog.google/products-and-platforms/products/search/google-search-personal-intelligence-apps/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="z-ai-发布-glm-5-4-750b-循环-transformer-28-层跑两遍" tabindex="-1">Z.ai 发布 GLM-5.4：750B 循环 Transformer，28 层跑两遍 <a class="header-anchor" href="#z-ai-发布-glm-5-4-750b-循环-transformer-28-层跑两遍" aria-label="Permalink to &quot;Z.ai 发布 GLM-5.4：750B 循环 Transformer，28 层跑两遍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-24">2026-11-24</time></p><p>Z.ai 推出首个循环 Transformer 旗舰 GLM-5.4，750B 规模下将 28 个 GLM-5 层运行两次以加深推理，已开放 API，开源权重待安全评估后发布。循环结构在不增加参数量的前提下提升深度。对读者：做编码类应用的团队可将其纳入评测，重点比较长任务下的稳定性与成本。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/23/zai-glm-5-4-loop-transformer/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="openai-与-cisco-推出开源-linux-运行时-shirudo" tabindex="-1">OpenAI 与 Cisco 推出开源 Linux 运行时 Shirudo <a class="header-anchor" href="#openai-与-cisco-推出开源-linux-运行时-shirudo" aria-label="Permalink to &quot;OpenAI 与 Cisco 推出开源 Linux 运行时 Shirudo&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/7d496f8d5755.webp" alt="配图"></p><p>OpenAI 与 Cisco 发布 Shirudo，一个面向 Linux 的开源运行时，帮助运维在滚动补丁期间保护运行中的系统。据 MarkTechPost 报道，它是 BSD 许可的 eBPF 运行时，AI Agent 编写签名的「护盾」来阻断漏洞利用路径。对读者：安全与平台团队可评估用其缩短高危漏洞的暴露窗口。</p><p class="news-entry-source"><a href="https://openai.com/index/introducing-shirudo" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="robotrack-面向真实机器人操作的点跟踪" tabindex="-1">RoboTrack：面向真实机器人操作的点跟踪 <a class="header-anchor" href="#robotrack-面向真实机器人操作的点跟踪" aria-label="Permalink to &quot;RoboTrack：面向真实机器人操作的点跟踪&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/ecdf9419b485.webp" alt="配图"></p><p>Ai2 在 Hugging Face 发布 RoboTrack，用点跟踪支持真实世界中的机器人操作任务。该工作聚焦于从视觉观测中稳定追踪关键点，以提升操作精度。对读者：做具身智能与机器人视觉的团队可关注其数据与模型开放情况。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/allenai/robotrack" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="anthropic-推出-claude-ship-agent-可评审、修复并批准代码变更" tabindex="-1">Anthropic 推出 Claude Ship，Agent 可评审、修复并批准代码变更 <a class="header-anchor" href="#anthropic-推出-claude-ship-agent-可评审、修复并批准代码变更" aria-label="Permalink to &quot;Anthropic 推出 Claude Ship，Agent 可评审、修复并批准代码变更&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/7a4ffd5646d5.webp" alt="配图"></p><p>Anthropic 发布 Claude Ship，打包 Code Review、PR Steward 与 Claude Approvals，让 Agent 评审、修复并批准 GitHub PR。Code Review 已正式可用，另两个 Agent 面向 Team 与 Enterprise 公测。对读者：AI 生成代码堆积时，可先用 PR Steward 接管失败 CI 与合并冲突等例行工作。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/23/anthropic-launches-claude-ship-letting-ai-agents-review-fix-and-approve-code-changes/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="ifood-如何在-1-5-万个仓库中规模化编码-agent" tabindex="-1">iFood 如何在 1.5 万个仓库中规模化编码 Agent <a class="header-anchor" href="#ifood-如何在-1-5-万个仓库中规模化编码-agent" aria-label="Permalink to &quot;iFood 如何在 1.5 万个仓库中规模化编码 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/dde34b8981a9.png" alt="配图"></p><p>iFood 在 15000 个代码仓库中部署编码 Agent，平台完成超过 25000 次运行，平均每次推理成本 0.04 美元，通过安全流程修复的漏洞数量翻倍以上。这给出了大规模 Agent 工程的成本与收益样本。对读者：规划编码 Agent 落地时，可参考其按仓库粒度治理与按运行计成本的思路。</p><p class="news-entry-source"><a href="https://openai.com/business/customer-stories/ifood" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="什么样的-chatgpt-应用才算好应用" tabindex="-1">什么样的 ChatGPT 应用才算好应用 <a class="header-anchor" href="#什么样的-chatgpt-应用才算好应用" aria-label="Permalink to &quot;什么样的 ChatGPT 应用才算好应用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Developer</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/7e4f598a6c82.png" alt="配图"></p><p>OpenAI 开发者博客讨论如何构建让对话更有效的 ChatGPT 应用能力，强调围绕对话场景设计功能而非简单移植现有界面。这为应用开发者提供了产品化指引。对读者：计划上架 ChatGPT 应用的团队可据此检查功能是否真正改善对话体验。</p><p class="news-entry-source"><a href="https://developers.openai.com/blog/what-makes-a-great-chatgpt-app" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="amazon-bedrock-推出-trusted-access-api-首批接入-claude-企业保障" tabindex="-1">Amazon Bedrock 推出 Trusted Access API，首批接入 Claude 企业保障 <a class="header-anchor" href="#amazon-bedrock-推出-trusted-access-api-首批接入-claude-企业保障" aria-label="Permalink to &quot;Amazon Bedrock 推出 Trusted Access API，首批接入 Claude 企业保障&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AWS Machine Learning</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/6f3135be0603.png" alt="配图"></p><p>Amazon Bedrock 上线可信访问计划 API，统一发现、申请与注册模型供应商计划。首批公测的是 Anthropic 的 Enterprise Frontier Safeguards 与 Enterprise Data Controls，用于 Claude Fable 模型的数据控制。对读者：企业采购 Claude 时可先通过该 API 完成合规登记，减少逐项对接成本。</p><p class="news-entry-source"><a href="https://aws.amazon.com/blogs/machine-learning/introducing-the-amazon-bedrock-trusted-access-api-with-anthropics-enterprise-frontier-safeguards-and-enterprise-data-controls/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="agent-集群需要的不只是一块消息板" tabindex="-1">Agent 集群需要的不只是一块消息板 <a class="header-anchor" href="#agent-集群需要的不只是一块消息板" aria-label="Permalink to &quot;Agent 集群需要的不只是一块消息板&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Stack Overflow Blog</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/9b1047efeaba.png" alt="配图"></p><p>Stack Overflow 博客指出，Agent 集群本质上是分布式系统问题，仅靠消息板无法解决一致性、协调与故障恢复。文章呼吁用分布式系统的成熟方法来设计多 Agent 协作。对读者：构建多 Agent 系统时，应优先考虑状态管理、幂等与可观测性，而非只加消息通道。</p><p class="news-entry-source"><a href="https://stackoverflow.blog/2026/11/24/agent-swarms-need-more-than-a-message-board/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="ladybird-浏览器发布首个-alpha-版本" tabindex="-1">Ladybird 浏览器发布首个 alpha 版本 <a class="header-anchor" href="#ladybird-浏览器发布首个-alpha-版本" aria-label="Permalink to &quot;Ladybird 浏览器发布首个 alpha 版本&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-24">2026-11-24</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/adf0e588a1af.webp" alt="配图"></p><p>Ladybird 发布首个 alpha，可安装试用。该项目自研 HTML 解析、CSS 引擎、布局、JavaScript 乃至 WebAssembly，仅复用 HarfBuzz、Skia、ffmpeg 与 SQLite 等少数外部组件。对读者：关注独立浏览器引擎的开发者可下载体验，并留意其对 Web 标准的覆盖进度。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/23/ladybird/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const m=a(s,[["render",i]]);export{g as __pageData,m as default};
